<?php include('head.php');
require_once __DIR__.'/report_engine.php';
if(session_status()===PHP_SESSION_ACTIVE)session_write_close();set_time_limit(120);
$today=new DateTime('today');$yesterday=clone $today;$yesterday->modify('-1 day');$defaultFrom=clone $yesterday;$defaultFrom->modify('-6 days');
$from=auditDate(filter_input(INPUT_GET,'from'),$defaultFrom->format('Y-m-d'));$to=auditDate(filter_input(INPUT_GET,'to'),$yesterday->format('Y-m-d'));auditRange($from,$to);
$loomId=auditLoom(filter_input(INPUT_GET,'loom'));$targetInput=filter_input(INPUT_GET,'target');$target=$targetInput===null||$targetInput===''?10000:(float)str_replace(',','.',(string)$targetInput);if(!is_finite($target)||$target<=0)throw new InvalidArgumentException('Sipariş metrajı sıfırdan büyük olmalıdır.');
$looms=$db->exec('SELECT IdTelaio,NomeTelaio FROM telaio WHERE EnableTelaio=1 AND IdTelaio<>100 ORDER BY IdTelaio');$endDate=clone $to;$endDate->modify('+1 day');
$daily=array();$planDaily=array();$qualities=array();$predecessors=null;$hasPartialDay=false;$completeDays=array();$cohort=null;
for($d=clone $from;$d<=$to;$d->modify('+1 day')){list($a,$b)=auditWindow($d,'day');unset($dataset);$dataset=auditDataset($db,$a,$b,$loomId?array($loomId):array(),array(),$predecessors);$predecessors=auditPredecessors($dataset);$r=auditMeasure($dataset,$a,$b);$s=auditSummary($r);$key=$d->format('Y-m-d');$daily[$key]=$s['length'];$qualities[]=$r['quality'];
if($b->getTimestamp()>$dataset['now']){$hasPartialDay=true;continue;}
$values=array();foreach($r['rows'] as $row)if($row['complete']&&$row['lengthReliable'])$values[$row['loomId']]=$row['lengthValue'];
$completeDays[$key]=$values;$cohort=$cohort===null?array_keys($values):array_values(array_intersect($cohort,array_keys($values)));}
$cohort=$cohort===null?array():$cohort;$total=0;$days=count($completeDays);
foreach($daily as $key=>$meters){$value=null;if(isset($completeDays[$key])&&$cohort){$value=0;foreach($cohort as $id)$value+=$completeDays[$key][$id];$total+=$value;}$planDaily[$key]=$value;}
$quality=auditMergeQuality($qualities);$quality['messages'][]='Kapasite tahmini yalnız seçili tamamlanmış günlerin hepsinde tam ve tutarlı kaydı bulunan ortak tezgâh grubuna dayanır. Plan kapsamı: '.($cohort?implode(', ',$cohort):'Uygun tam gün kaydı yok').'.';
if($hasPartialDay)$quality['messages'][]='Tamamlanmamış günlerdeki kayıtlı üretim tabloda görünür; kapasite ortalamasına katılmaz.';
$dailyCapacity=$cohort&&$days?$total/$days:null;$neededDays=$dailyCapacity!==null&&$dailyCapacity>0?ceil($target/$dailyCapacity):null;
$finishDate=clone $today;$finishDate->modify('+1 day');if($neededDays!==null)$finishDate->modify('+'.max(0,$neededDays-1).' days');?>
